from qgis.core import QgsProcessingAlgorithm, QgsProcessingParameterFeatureSource, QgsProcessingParameterFeatureSink

class CustomAlgorithm(QgsProcessingAlgorithm):
    def name(self): return 'custom_algo'
    def displayName(self): return 'Custom Algorithm'
    def group(self): return 'GIS Development Skills'
    def groupId(self): return 'gis_dev_skills'
    def initAlgorithm(self, config=None):
        self.addParameter(QgsProcessingParameterFeatureSource('INPUT', 'Input layer'))
        self.addParameter(QgsProcessingParameterFeatureSink('OUTPUT', 'Output layer'))
    def processAlgorithm(self, parameters, context, feedback):
        source = self.parameterAsSource(parameters, 'INPUT', context)
        (sink, dest_id) = self.parameterAsSink(parameters, 'OUTPUT', context, source.fields(), source.wkbType(), source.sourceCrs())
        return {'OUTPUT': dest_id}

