import xml.etree.ElementTree as ET

def parse_kml_colors(kml_bytes):
    root = ET.fromstring(kml_bytes)
    ns = {'kml': 'http://www.opengis.net/kml/2.2'}
    styles = {}
    for style in root.findall('.//kml:Style', ns):
        sid = style.get('id')
        color = style.find('.//kml:color', ns)
        if sid and color is not None:
            # aabbggrr -> #rrggbbaa conversion
            c = color.text.strip()
            styles[sid] = f'#{c[6:8]}{c[4:6]}{c[2:4]}{c[0:2]}' if len(c) == 8 else f'#{c}'
    return styles

